declarations.body:
fun x =>
  match x with
  | BlockDotProduct.ReductionTree.empty => List.nil.{0}
  | BlockDotProduct.ReductionTree.leaf j => List.cons.{0} j List.nil.{0}
  | BlockDotProduct.ReductionTree.node l r =>
    HAppend.hAppend.{0, 0, 0} (BlockDotProduct.ReductionTree.leaves l) (BlockDotProduct.ReductionTree.leaves r)

declarations.type:
∀ {mul blockAdd : Nat → Nat → Real} {treeAdd : Nat → Real} {mul_1 blockAdd_1 : Nat → Nat → Real}
  {treeAdd_1 : Nat → Real},
  Eq.{1} { mul := mul, blockAdd := blockAdd, treeAdd := treeAdd }
      { mul := mul_1, blockAdd := blockAdd_1, treeAdd := treeAdd_1 } →
    And (Eq.{1} mul mul_1) (And (Eq.{1} blockAdd blockAdd_1) (Eq.{1} treeAdd treeAdd_1))

∀ (mul blockAdd : Nat → Nat → Real) (treeAdd : Nat → Real) (mul_1 blockAdd_1 : Nat → Nat → Real)
  (treeAdd_1 : Nat → Real),
  Eq.{1}
    (Eq.{1} { mul := mul, blockAdd := blockAdd, treeAdd := treeAdd }
      { mul := mul_1, blockAdd := blockAdd_1, treeAdd := treeAdd_1 })
    (And (Eq.{1} mul mul_1) (And (Eq.{1} blockAdd blockAdd_1) (Eq.{1} treeAdd treeAdd_1)))
